## Code Example
```javascript
function hashFeatureKeys(keys) {
  // simple 1024-bin hash
  const bins = new Array(1024).fill(0);
  for (const k of Object.keys(keys)) {
    const hash = [...k].reduce((a,c)=> (a*31+c.charCodeAt(0))>>>0, 7);
    bins[hash % 1024] += keys[k];
  }
  return bins;
}
```

